from pathlib import Path
import json
R=Path(__file__).resolve().parent
notes=[]
def make(scene,direction,name,question,operation,idea,body,css='',script='',risk='',suppressed='Detailed chapter text and actual enterprise readiness.'):
 p=R/scene/('direction-'+direction);p.mkdir(parents=True,exist_ok=True)
 note={'name':name,'reader_question':question,'reasoning_operation':operation,'visual_idea':idea,'why_geometry_helps':idea,'interaction_if_any':'Native labelled controls expose the relevant object or consequence; no hover dependency.','false_inference_risk':risk,'references_used':['Supplied Design Board-8: simultaneous source, interpretation and responsibility','Supplied Design System-15: material distinction, authored scale and quiet chrome'],'what_is_deliberately_not_shown':suppressed}
 (p/'direction-note.json').write_text(json.dumps(note,indent=2)+'\n');notes.append({'scene':scene,'direction':direction,**note})
 nav=''.join(f'<a href="../../{s}/direction-a/">{i+1:02} / {label}</a>' for i,(s,label) in enumerate([('overview','Work'),('knowledge','Knowledge'),('change','Change')]))
 dirs=''.join(f'<a href="../direction-{d}/" '+('aria-current="page"' if d==direction else '')+f'>{d.upper()}</a>' for d in 'abc')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>{name} · CLM AI</title><link rel="stylesheet" href="../../shared/base.css"><style>{css}</style></head><body class="revision-on" data-task="develop" data-meaning="source"><header class="top"><a class="brand" href="../../">CLM / AI <small>Knowledge Hub</small></a><nav>{nav}</nav><div class="directions" aria-label="Composition direction">{dirs}</div></header><main class="canvas">{body}</main><footer class="lab-footer"><span>Composition study · {name} · 1920×1200</span><span>Synthetic teaching material · no deployment or institutional approval</span></footer><dialog aria-label="Specimen scope"><span class="label">Source & authority</span><h2>Teaching specimen</h2><p>This is an authored illustration from the Hub's synthetic objects. It is not an actual SEB instruction, legal interpretation or deployed FenX behaviour.</p><p>A task review and a reuse review answer different questions. Actual ownership, applicability, permitted consumption and observed results remain to be established.</p><button data-close>Return to the composition</button></dialog><script src="../../shared/interaction.js"></script>{script}</body></html>'''
 (p/'index.html').write_text(html)
def intro(kicker,title,desc):return f'<div class="intro"><div><p class="label">{kicker}</p><h1>{title}</h1></div><p>{desc}</p></div>'
def defs():return '<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="none" stroke="#718a74"/></marker><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8L8 0" stroke="#c1cdb8" stroke-width=".6"/></pattern></defs>'
def svg(content,view='0 0 1360 700',label='Explanatory relationship'):return f'<svg class="graphic" viewBox="{view}" role="img" aria-label="{label}">{defs()}{content}</svg>'
def boundary(text):return '<div class="boundary"><span>'+text+'</span><span>Illustrative relationships · not current architecture</span></div>'
# OVERVIEW A — whole-width work landscape, three semantic corridors.
lanes=''
for i,(id,title,verbs,out) in enumerate([('run','Run CLM','Retrieve · structure · prepare','Source-linked preparation'),('develop','Develop CLM','Analyse · draft · test','Requirement + adverse test'),('change','Govern / change CLM','Compare · trace · challenge','Impact-review candidates')]):
 y=85+i*150
 lanes+=f'''<g data-group="{id}"><path d="M70 {y+26}L830 {y+26}L895 {y-12}L1148 {y-12}L1218 {y+70}L830 {y+70}L70 {y+70}Z" fill="{'#d9e4ce' if id=='develop' else '#e9ecdf'}"/><text x="82" y="{y}" class="t-title">{title}</text><text x="372" y="{y+55}" font-size="23">{verbs}</text><path d="M735 {y+50}H880" class="line" marker-end="url(#arrow)"/><text x="790" y="{y+15}" class="t-small">prepares</text><g transform="translate(1000,{y-13}) rotate(-4)"><path d="M0 0H190L210 20V100H0Z" class="source-fill"/><path d="M190 0V20H210" class="fine" fill="none"/><text x="18" y="30" class="t-label">FOR REVIEW</text><text x="18" y="57" font-size="14">{out}</text><path d="M18 73H180M18 84H130" class="fine"/></g></g>'''
land=svg(f'''<text x="70" y="28" class="t-label">USEFUL WORK · THREE REPRESENTATIVE ROUTES</text>{lanes}<path d="M928 35V470" stroke="#9b875c" stroke-width="3"/><text x="932" y="490" class="t-small">Human review</text><text x="1000" y="518" class="t-small">No authoritative action implied</text><path d="M80 640L190 550H870L760 640Z" fill="#e1e7d5" stroke="#bfcbb7"/><path d="M80 640V660H760V640" fill="#c9d6c0"/><text x="155" y="588" font-size="24">Context that gives the work meaning</text><text x="155" y="618" class="t-small">Rules & instructions · process / system knowledge · methods · evidence</text><path d="M225 550V128M225 277H325M225 428H325M225 128H325" class="line" marker-end="url(#arrow)"/><text x="238" y="527" class="t-small">informs the task</text><path d="M1215 445C1320 470 1290 600 930 600" class="candidate" marker-end="url(#arrow)"/><text x="972" y="635" class="t-small">Selected artifacts only</text><text x="925" y="664" font-size="17">A separate review defines reuse</text>''',label='Three CLM work routes use shared context; prepared output meets human review; selected artifacts require separate reuse review')
body=intro('01 / Work, context and responsibility','How AI fits into<br>CLM work.','AI helps with preparation, development and change. The question is what the task can use—and what a colleague must still decide.')+f'''<div class="land-layout"><div><div class="controls" aria-label="Inspect a work route"><button data-task="run">Run CLM</button><button data-task="develop">Develop CLM</button><button data-task="change">Govern / change</button></div>{land}</div><aside class="readout landscape-note"><p class="label">Selected route</p><h2 data-task-field="title">Develop a FenX behaviour</h2><p class="verb" data-task-field="verbs"></p><dl><div><dt>Uses</dt><dd data-task-field="source"></dd></div><div><dt>Produces</dt><dd data-task-field="output"></dd></div></dl><div class="gate"><strong>Human responsibility</strong><p data-task-field="human"></p></div><p class="scope" data-task-field="scope"></p><button class="inspect" data-inspect="Task scope and source">Inspect the scope</button></aside></div><div class="operation-strip"><span class="label">How far it can extend</span><p><strong>Supplied material</strong> can support bounded work now. Live information needs a real interface. Shared assistance adds operation and ownership.</p><label><input type="checkbox" data-interface-toggle> Assume a data interface</label><p data-interface-message>No interface assumed. Supplied-document work can still proceed.</p></div>'''+boundary('Review for this task and review for reuse are separate decisions.')
make('overview','a','The working landscape','How do work, context and review connect?','Trace','Three work corridors share a contextual base, meet a review seam and leave a separate reuse route.',body,'.land-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:48px}.landscape-note{border-left:1px solid #cbd4c5;padding:30px 0 0 30px}.landscape-note h2{font-size:30px}.landscape-note .verb{font-size:13px;margin-top:14px;color:#6b7a6c}.landscape-note .scope{font-size:13px;margin-top:22px}.operation-strip{display:grid;grid-template-columns:170px 1fr 250px 320px;gap:28px;border-top:1px solid #cbd4c5;padding-top:22px;font-size:13px}.operation-strip strong{font-weight:400;color:#003b2b}.operation-strip label{display:flex;gap:10px;align-items:start}.operation-strip input{accent-color:#003b2b}.land-layout .graphic{margin-top:14px}.intro{margin-bottom:25px}',risk='A continuous corridor could be read as automatic workflow execution; review seam and scope explicitly stop that inference.')
# OVERVIEW B — editorial desk: source, intention and output in one large material scene.
body=f'''<div class="desk-layout"><section class="desk-editorial"><p class="label">01 / A work-centred explanation</p><h1>Useful work.<br>Context that<br>travels with it.</h1><p class="desk-lead">AI can help prepare, develop and examine CLM work. The context behind the output matters just as much as the output.</p><div class="desk-choices"><button data-task="run"><span>01</span> Prepare an observation</button><button data-task="develop"><span>02</span> Develop a behaviour</button><button data-task="change"><span>03</span> Examine a change</button></div><div class="gate"><strong>Start with a bounded task</strong><p>Define what good looks like before asking AI to produce it.</p></div></section><section class="desk-scene" aria-label="An annotated work desk">{svg('<path d="M200 170C500 170 350 530 660 530S1080 550 1060 750" class="line" marker-end="url(#arrow)"/><path d="M1050 830C500 980 150 800 190 560" class="candidate" marker-end="url(#arrow)"/>','0 0 1200 930')}<article class="paper source-desk"><span class="label">What gives the task meaning</span><h3>Relevant instructions.<br>Known system behaviour.</h3><p>Preserve the source, subject, version and missing facts.</p><div class="folio-lines"><span></span><span></span><span></span></div><footer>Applicability is reviewed for this task.</footer></article><article class="intent-slip"><span class="label">Human framing</span><h3>“What must this<br>behaviour preserve?”</h3><p>Business intent · constraints · acceptance</p></article><article class="paper output-desk ink"><span class="label">AI-assisted work · illustrative output</span><h2 data-task-field="title"></h2><p class="verbs" data-task-field="verbs"></p><div class="output-ruled"><small>Useful contribution</small><p data-task-field="output"></p></div><div class="output-ruled"><small>Responsibility</small><p data-task-field="human"></p></div><footer data-task-field="scope"></footer></article><div class="reuse-desk"><span class="label">A different review question</span><h3>Could another task use this?</h3><p>Only selected artifacts. Establish applicability, ownership, maintenance and permitted consumption.</p><button class="inspect" data-inspect="Reuse review">Inspect the reuse boundary</button></div><div class="desk-margin"><strong>Data access ≠ runtime</strong><p>Supplied-document analysis may need neither a live interface nor an AI model in the resulting production feature.</p></div></section></div>'''
make('overview','b','The annotated work desk','Why does useful output depend on context and review?','Explain','Large source, intent and output fragments occupy one authored desk; a return annotation makes reuse a separate question.',body,'.desk-layout{display:grid;grid-template-columns:420px 1fr;gap:50px}.desk-editorial{padding-top:38px}.desk-editorial h1{font-size:69px;margin:28px 0}.desk-lead{font-size:19px;line-height:1.65;color:#637264}.desk-choices{display:grid;margin:40px 0}.desk-choices button{text-align:left;padding:18px 0;border-top:1px solid #cbd4c5;font-size:20px}.desk-choices span{font-size:12px;display:inline-block;width:35px}.desk-scene{position:relative;height:950px}.desk-scene>.graphic{position:absolute;inset:0;width:100%;height:100%;z-index:0}.source-desk{position:absolute;left:3%;top:20px;width:440px;transform:rotate(-4deg)}.intent-slip{position:absolute;left:51%;top:75px;border-left:2px solid #a5925e;padding:15px 26px;transform:rotate(2deg)}.intent-slip h3{font-size:28px;margin:20px 0}.intent-slip p{font-size:13px}.output-desk{position:absolute;left:32%;top:340px;width:550px;transform:rotate(1deg);box-shadow:20px 25px 0 -10px #cddac4}.output-desk h2{font-size:38px}.output-desk .verbs{font-size:14px;color:#afc6b5;margin:20px 0}.output-ruled{border-top:1px solid #4d6b5a;padding:16px 0}.output-ruled p{font-size:17px;margin-top:7px}.output-desk footer{color:#cad7c7;border-color:#4d6b5a}.reuse-desk{position:absolute;left:0;bottom:60px;width:350px}.reuse-desk h3{margin:15px 0}.reuse-desk p{font-size:14px}.desk-margin{position:absolute;right:0;bottom:5px;max-width:470px;font-size:13px;border-top:1px solid #b9c8b5;padding-top:20px}.desk-margin strong{font-size:19px;font-weight:400;display:block;margin-bottom:8px}',risk='Overlapping papers could hide the actual sequence; printed annotations state framing, contribution and separate reuse.')
# OVERVIEW C — score-like simultaneous comparison, not a work flow diagram.
rows=''
for i,(id,label,context,verb,output,review) in enumerate([('run','Run CLM','Passage · subject · field meaning','Retrieve / prepare','Observation with source & gaps','Verify fidelity and missing information'),('develop','Develop CLM','Instruction · system context','Draft / test','Requirement with acceptance logic','Confirm intended behaviour and evidence'),('change','Govern / change','Revision · interpretation','Compare / trace','Impact-review candidates','Decide applicability and controlled change')]):
 rows+=f'<section class="score-row" data-group="{id}"><button class="score-work" data-task="{id}"><small>0{i+1}</small><h2>{label}</h2></button><div class="score-context">{context}<span>informs →</span></div><div class="score-verb">{verb}<span class="score-track"></span></div><div class="score-review"><span class="label">Human review</span><p>{review}</p></div><div class="score-output"><span class="label">Prepared artifact</span><h3>{output}</h3></div></section>'
body=intro('01 / Three contributions, one discipline','The work changes.<br>The responsibility remains.','Read across one row: the task uses context, AI assists within it, and a colleague determines what the output can support.')+f'<div class="score-head"><span>CLM work</span><span>Relevant context</span><span>Bounded assistance</span><span>Where judgement acts</span><span>Inspectable output</span></div><div class="score">{rows}</div><div class="score-bottom"><div><p class="label">A separate route</p><h2>Selected work can inform<br>another task.</h2></div><div><p>Task acceptance does not establish reuse. Review purpose, meaning, version, ownership and permitted consumption.</p><button class="inspect" data-inspect="Reuse scope">Inspect what travels with the artifact</button></div><aside class="score-detail"><span class="label">Selected route</span><h3 data-task-field="title"></h3><p data-task-field="scope"></p></aside></div>'+boundary('Data, interfaces and operating environments determine how assistance extends; they are not a universal on/off gate.')
make('overview','c','The work score','What changes across Run, Develop and Govern/change?','Compare','Three horizontal scores align context, contribution, review and output without claiming automation or quantities.',body,'.score-head,.score-row{display:grid;grid-template-columns:310px 310px 330px 330px 1fr;gap:32px}.score-head{font-size:12px;color:#667b69;padding:10px 0 25px}.score-row{padding:34px 0;border-top:1px solid #c6d0bf;min-height:205px;align-items:center;transition:opacity .2s}.score-row.dim{opacity:.5}.score-work{text-align:left}.score-work h2{font-size:32px;margin-top:12px}.score-context{font-size:18px}.score-context span{display:block;margin-top:28px;font-size:12px;color:#7b866e}.score-verb{font-size:24px}.score-track{height:3px;background:#92a58b;width:100%;display:block;margin-top:30px}.score-review{border-left:3px double #a28c56;padding:15px 25px}.score-review p{margin-top:12px}.score-output{border-top:1px solid #798e73;border-bottom:1px solid #798e73;padding:18px 0}.score-output h3{font-size:22px;margin-top:15px}.score-bottom{display:grid;grid-template-columns:1fr 1fr 1fr;gap:70px;border-top:1px solid #819878;margin-top:16px;padding-top:35px}.score-bottom p{font-size:15px}.score-detail{padding-left:26px;border-left:1px solid #bfcbb7}.score-detail h3{margin:12px 0}',risk='Alignment could imply all tasks have the same review process; review wording differs per route and no automatic action is drawn.')
# KNOWLEDGE A — source-to-field annotation loom.
q='What must remain attached when knowledge enters a task?'
source='Record the stated wealth-origin event and its source. Keep absent amounts and corroboration unresolved. Separate preparation from verification and plausibility judgement.'
body=intro('02 / Knowledge becomes usable','Keep the meaning.<br>Make the context explicit.','Structuring a document changes its form. Applicability, reuse and execution remain separate questions.')+f'''<div class="loom"><article class="loom-source"><div class="document-tab">READABLE INSTRUCTION <span>INS-01@1</span></div><div class="source-page"><span class="label">Synthetic · reviewed for this example only</span><h2>Preserve what<br>the source says.</h2><p class="source-clause" data-meaning-part="source"><span>01</span>Record the stated wealth-origin event <mark>and its source.</mark></p><p class="source-clause" data-meaning-part="absence"><span>02</span>Keep absent amounts and corroboration <mark>unresolved.</mark></p><p class="source-clause" data-meaning-part="boundary"><span>03</span><mark>Separate preparation</mark> from verification and plausibility judgement.</p><footer>Scope: this synthetic natural-person preparation task.<br>No new source authority is created by encoding it.</footer></div></article><div class="loom-bridge">{svg('<path d="M0 100C90 100 20 160 100 160M0 250C85 250 20 290 100 290M0 410C85 410 20 440 100 440" class="line" marker-end="url(#arrow)"/><text x="15" y="560" transform="rotate(-90 15 560)" class="t-label">MEANING PRESERVED · FORM CHANGED</text>','0 0 100 640','Source propositions map to explicit structured fields')}</div><section class="loom-record"><span class="label">The same instruction · structured representation</span><h2>Context record</h2><div class="record-key"><span class="mono">id</span><strong>INS-01@1</strong></div><button class="record-field" data-meaning="source" aria-pressed="true"><span class="mono">source / version</span><p>Original instruction, v1</p><small>Keep its provenance attached.</small></button><button class="record-field" data-meaning="absence"><span class="mono">missing_information</span><p>Amount · corroboration</p><small>Absent stays absent.</small></button><button class="record-field" data-meaning="boundary"><span class="mono">task_boundary</span><p>Preparation only</p><small>No verification or plausibility outcome.</small></button><div class="record-scope"><span class="label">Applicability</span><p>Illustrative task only.<br>Other use needs review.</p></div></section><aside class="loom-use"><p class="label">Where another requirement begins</p><h2>A task needs<br>a consumption route.</h2><div class="gate"><strong>Human reuse review</strong><p>Purpose, subject, version, ownership and permitted consumption.</p></div><article class="method-sheet"><span class="label">Method · METHOD-01@1</span><h3>Identify → map cautiously<br>→ cite → expose gaps</h3><p>A harness must supply the context, tools and constraints in a suitable environment.</p></article><div class="meaning-readout" aria-live="polite"><div data-meaning-detail="source"><span class="label">Selected: provenance</span><p>A source pointer lets a colleague inspect the basis. It is not independent verification.</p></div><div data-meaning-detail="absence" hidden><span class="label">Selected: missing facts</span><p>The observation must expose missing amount and corroboration. Structure cannot supply either.</p></div><div data-meaning-detail="boundary" hidden><span class="label">Selected: task scope</span><p>The candidate is preparation for review. It must not become a customer assessment or authoritative update.</p></div></div></aside></div>'''+boundary('Human-readable → machine-readable is a representation change. It is not an approval or an execution permission.')
make('knowledge','a','The annotation loom',q,'Trace','Literal source propositions align with structured fields, followed by a visibly separate consumption boundary.',body,'.loom{display:grid;grid-template-columns:minmax(0,1.2fr) 90px minmax(0,.95fr) minmax(0,1fr);gap:28px;align-items:start}.loom-source{background:#fffefa;box-shadow:12px 15px 0 -6px #dfe5d5}.document-tab{padding:18px 26px;border-block:1px solid #9caf95;font-size:12px;display:flex;justify-content:space-between}.document-tab span{font-family:monospace}.source-page{padding:32px}.source-page h2{font-size:40px;margin:28px 0 32px}.source-clause{position:relative;font-size:23px;line-height:1.55;padding:22px 0 22px 32px;border-top:1px solid #d9dfcf;transition:opacity .2s}.source-clause span{position:absolute;left:0;top:28px;font-size:11px;color:#87937e}.source-page footer{font-size:12px;color:#7b836d;border-top:1px solid #d9dfcf;padding-top:25px;margin-top:20px}.loom-bridge{padding-top:142px}.loom-record{padding:26px 0}.loom-record h2{margin:25px 0}.record-key{display:flex;justify-content:space-between;border-bottom:1px solid #afbea7;padding:20px 0;font-size:16px}.record-key strong{font-weight:400}.record-field{display:block;text-align:left;width:100%;padding:24px 12px;border-bottom:1px solid #cdd8c3;border-left:2px solid transparent}.record-field[aria-pressed=true]{background:#e3e9d8;border-left-color:#64855a;border-bottom:1px solid #cdd8c3}.record-field p{font-size:22px;margin:10px 0}.record-scope{padding:24px 12px;border-bottom:1px solid #a9b79f}.record-scope p{font-size:18px;margin-top:10px}.loom-use{padding:24px 0 0 34px;border-left:1px solid #bfcbb5}.loom-use h2{font-size:33px;margin:25px 0}.loom-use .gate{margin:30px 0}.method-sheet{padding:24px 0;border-block:1px solid #acbba1}.method-sheet h3{font-size:24px;margin:20px 0}.method-sheet p{font-size:14px;color:#6e7e68}.meaning-readout{padding-top:25px;font-size:16px}.meaning-readout p{margin-top:12px}.dim{opacity:.3}',risk='A connector may imply automatic interpretation; the source-to-record step explicitly adds no authority, and the consumption boundary remains unresolved.')
# KNOWLEDGE B — exploded anatomy of a record.
planes=svg('''<path d="M230 155L660 60L995 240L555 345Z" fill="#fffef9" stroke="#a9b99e"/><path d="M230 155V176L555 367V345" fill="#e0e6d5"/><path d="M555 345L995 240V261L555 367Z" fill="#c8d4ba"/><path d="M230 330L660 235L995 415L555 520Z" fill="#dce7d1" stroke="#a9b99e"/><path d="M230 330V348L555 541V520" fill="#c4d3b4"/><path d="M555 520L995 415V434L555 541Z" fill="#aabd96"/><path d="M230 505L660 410L995 590L555 695Z" fill="#003b2b"/><path d="M230 505V525L555 716V695" fill="#0f503a"/><path d="M555 695L995 590V610L555 716Z" fill="#002c20"/><path d="M660 60V410M230 155V505M995 240V590" class="candidate"/><path d="M340 180L650 111M380 203L710 131M420 225L772 150" class="fine"/><path d="M360 360L655 296M405 385L715 316M450 409L770 337" stroke="#9baf8c" fill="none"/><path d="M370 542L660 475M415 565L718 497" stroke="#5b8464" fill="none"/><text x="510" y="244" class="t-title">Meaning</text><text x="510" y="420" class="t-title">Scope</text><text x="490" y="596" class="t-title t-white">Provenance</text><path d="M230 170H65M230 343H65M230 518H65" class="line"/><text x="65" y="148" font-size="18">What it says</text><text x="65" y="321" font-size="18">Where it applies</text><text x="65" y="496" font-size="18">Where it came from</text><text x="300" y="770" class="t-small">Attached parts of one record · not a maturity ladder</text>''','0 0 1100 820','Exploded anatomy: meaning, scope and provenance stay attached to the same instruction')
body='''<div class="anatomy-heading"><div><p class="label">02 / An instruction is more than text</p><h1>Keep its meaning,<br>scope and source<br>together.</h1></div><aside><span class="mono">INS-01@1</span><p class="status">Synthetic · example scope only</p><p>A structured record can carry context into another task. It cannot decide whether that task may use it.</p></aside></div><div class="anatomy-layout"><section class="anatomy-figure">'''+planes+'''</section><aside class="anatomy-inspector ink"><div class="selection-toggle"><button data-meaning="source" aria-pressed="true">Source</button><button data-meaning="absence">Meaning</button><button data-meaning="boundary">Scope</button></div><div data-meaning-detail="source"><p class="label">Provenance stays attached</p><h2>INS-01@1</h2><blockquote>“Record the stated wealth-origin event and its source.”</blockquote><p>Teaching instruction, version 1. No legal or institutional authority is asserted.</p></div><div data-meaning-detail="absence" hidden><p class="label">Meaning stays explicit</p><h2>Absent stays absent.</h2><blockquote>“Keep absent amounts and corroboration unresolved.”</blockquote><p>Encoding a field does not create the missing fact.</p></div><div data-meaning-detail="boundary" hidden><p class="label">Scope stays bounded</p><h2>Preparation only.</h2><blockquote>“Separate preparation from verification and plausibility judgement.”</blockquote><p>Other task applicability remains a human review question.</p></div><div class="anatomy-stop"><span>Before another task consumes it</span><h3>Review applicability.<br>Establish ownership.<br>Define permitted use.</h3></div><footer>Methods guide the task. A harness coordinates it.<br>An actual runtime supplies the environment.<br>A document is not automatically an executable skill.</footer></aside></div>'''
make('knowledge','b','The exploded record',q,'Inspect','An exploded object separates meaning, scope and provenance while preserving one identity, beside the review boundary.',body,'.anatomy-heading{display:flex;justify-content:space-between;align-items:start;gap:100px}.anatomy-heading h1{font-size:64px;margin-top:20px}.anatomy-heading>aside{max-width:400px;padding:30px 0}.anatomy-heading>aside>p{margin-top:22px;font-size:17px}.anatomy-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,.8fr);gap:80px;margin-top:-80px;align-items:end}.anatomy-figure{margin-top:80px}.anatomy-inspector{padding:35px 38px 30px;margin-bottom:24px}.anatomy-inspector h2{font-size:36px;margin:26px 0}.anatomy-inspector blockquote{font-size:24px;line-height:1.5;margin:25px 0}.anatomy-inspector p{font-size:15px;color:#cad7c5}.anatomy-inspector .selection-toggle{border-color:#66836a}.anatomy-inspector button[aria-pressed=true]{color:#fff;border-color:#cbd4bb}.anatomy-stop{border-left:2px solid #c4b582;padding:10px 22px;margin:32px 0}.anatomy-stop>span{font-size:12px;color:#becfb8}.anatomy-stop h3{font-size:24px;margin-top:17px;line-height:1.5}.anatomy-inspector footer{font-size:12px;border-top:1px solid #638266;padding-top:20px}',risk='Vertical depth may imply maturity or approval; the caption defines the three planes as attached record parts. The actual source remains one version.')
# KNOWLEDGE C — selective context, reservoir vs packet.
body=intro('02 / Selection, not accumulation','All the knowledge is not<br>the context for every task.','A useful context packet is a deliberate selection. Keep the reason for inclusion—and the gaps—visible.')+'''<div class="aperture"><section class="context-reservoir"><p class="label">Candidate material · conceptual families</p><h2>What could inform<br>the work</h2><label><input type="checkbox" checked data-include="rule"><span>Rules & instructions<small>What applies, and why</small></span></label><label><input type="checkbox" checked data-include="context"><span>Process & system context<small>Subject, journey, field meaning</small></span></label><label><input type="checkbox" checked data-include="method"><span>Methods & boundaries<small>How to prepare and what to leave unresolved</small></span></label><div class="reservoir-scope"><strong>Review is selective</strong><p>Unrelated subjects, obsolete versions and unsupported assumptions do not become useful context by inclusion.</p></div></section><div class="aperture-field">'''+svg('''<path d="M0 90C250 90 250 230 570 230M0 280C250 280 250 280 570 280M0 470C250 470 250 330 570 330" stroke="#bdcdb1" stroke-width="38" fill="none"/><path d="M0 90C250 90 250 230 570 230" class="line" data-inclusion="rule"/><path d="M0 280C250 280 250 280 570 280" class="line" data-inclusion="context"/><path d="M0 470C250 470 250 330 570 330" class="line" data-inclusion="method"/><path d="M340 105V450" stroke="#8e7c4e" stroke-width="4"/><text x="355" y="130" class="t-label">HUMAN REVIEW</text><text x="355" y="165" font-size="20">Purpose</text><text x="355" y="194" font-size="20">Applicability</text><text x="355" y="400" font-size="20">Ownership</text><text x="355" y="429" font-size="20">Permitted use</text><text x="110" y="580" class="t-small">Widths indicate no quantity or coverage.</text>''','0 0 620 660','Candidate context is selected through human review; widths do not encode quantity')+'''</div><article class="packet paper"><span class="label">A bounded task packet · illustration</span><h2>Prepare a<br>source-linked observation.</h2><div class="packet-row" data-inclusion="rule"><small>Instruction</small><p>INS-01@1 · preserve source and gaps</p></div><div class="packet-row" data-inclusion="context"><small>Relevant context</small><p>Correct subject and field meaning</p></div><div class="packet-row" data-inclusion="method"><small>Method</small><p>Identify · map cautiously · cite · expose gaps</p></div><div class="packet-review" data-packet-status>Context selected; applicability, ownership and consumption still need review.</div><footer>A harness must actually supply and constrain this context. No live agent or runtime is asserted.</footer></article></div><div class="notes"><div><strong>Knowledge informs</strong><p>Relevant meaning and facts enter the task.</p></div><div><strong>Methods guide</strong><p>The procedure and its limits remain inspectable.</p></div><div><strong>Tools provide capability</strong><p>A permitted interface and suitable runtime remain separate requirements.</p></div></div>'''
make('knowledge','c','The context aperture',q,'Select','Candidate context narrows through an explicit review aperture into one task packet; unselected context leaves a visible gap.',body,'.aperture{display:grid;grid-template-columns:420px minmax(0,1fr) 470px;gap:40px;align-items:center}.context-reservoir{padding:28px 0}.context-reservoir h2{font-size:38px;margin:25px 0 35px}.context-reservoir label{display:flex;gap:18px;font-size:22px;padding:28px 0;border-top:1px solid #bfcdb5;cursor:pointer}.context-reservoir input{accent-color:#003b2b;width:18px;height:18px;margin-top:8px}.context-reservoir small{display:block;margin-top:6px;font-size:14px}.reservoir-scope{padding:25px 20px;border-left:2px solid #a39365;margin-top:15px}.reservoir-scope strong{font-size:19px;font-weight:400}.reservoir-scope p{font-size:14px;margin-top:10px}.packet h2{font-size:36px;margin-bottom:30px}.packet-row{border-top:1px solid #cad3c1;padding:22px 0;transition:opacity .2s}.packet-row p{font-size:18px;margin-top:9px}.packet-review{font-size:15px;background:#eee8d4;padding:18px;margin-top:15px}.dim{opacity:.25}',risk='A funnel could imply quantitative filtering or automatic approval; widths encode no amount, controls select candidate material only.')
# CHANGE A — split impact field, document fragments and a stopped implementation path.
change_controls='<div class="controls"><label><input type="checkbox" checked data-revision-toggle> Inspect the proposed revision</label><span class="small" data-revision-status>Proposed revision selected · impact review only</span></div>'
body=intro('03 / Instruction change · synthetic onboarding handoff','A revision changes<br>the questions to review.','Trace a single change through its possible consequences. Dependency identifies review work; it does not update the system.')+change_controls+'''<div class="impact-field"><article class="revision-folio"><span class="label">CHG-INS@1 → candidate CHG-INS@2</span><h2>Describe the<br>missing item.</h2><p class="baseline-rule">Baseline instruction</p><div class="revision-addition" data-revision><span class="label">Proposed addition</span><p>Keep its <mark>source pointer</mark> and the <mark>follow-up role</mark>—or state that responsibility is unresolved.</p><span class="status proposed">Requires review</span></div><div class="gate"><strong>Applicability first</strong><p>A person determines whether this proposed instruction belongs in the real workflow.</p></div></article><div class="impact-tree">'''+svg('''<path d="M10 125H120C180 125 180 75 240 75H330" class="candidate" marker-end="url(#arrow)" data-revision/><path d="M120 125C180 125 180 370 240 370H330" class="candidate" marker-end="url(#arrow)" data-revision/><text x="118" y="190" class="t-small">triggers</text><text x="118" y="215" class="t-small">impact review</text><path d="M310 260V300" class="line" marker-end="url(#arrow)"/><text x="325" y="287" class="t-small">challenged by</text><path d="M590 120H760" class="candidate" marker-end="url(#arrow)"/><path d="M710 80V180" stroke="#a28b57" stroke-width="3"/><text x="640" y="220" class="t-small">Human change decision</text><text x="740" y="70" class="t-small">Implementation</text><text x="740" y="98" class="t-small">not supplied</text><path d="M10 620H240" class="line"/><text x="30" y="655" class="t-small">remains pinned to v1</text><path d="M580 620H790" class="candidate"/><path d="M685 600L710 640M710 600L685 640" stroke="#a28b57" stroke-width="2"/><text x="612" y="678" class="t-small">does not verify candidate v2</text>''','0 0 1000 730','Proposed revision triggers requirement and test review; implementation requires a human decision; v1 evidence does not verify v2')+'''<article class="impact-requirement" data-revision><span class="label">CHG-REQ@1 · requirement candidate</span><h3>Preserve the handoff gap<br>and its provenance.</h3><p>Keep description, source and responsibility status visible. Unknown ownership stays unknown.</p></article><article class="impact-test" data-revision><span class="label">CHG-TEST@1 · proposed adverse test</span><h3>What if no follow-up<br>owner is known?</h3><dl><div><dt>Expect</dt><dd>No invented person.<br>No completion inference.</dd></div><div><dt>Result</dt><dd>Not supplied</dd></div></dl></article><article class="impact-evidence"><span class="label">CHG-EVID@1 · retained scope</span><h3>Version 1 remains version 1.</h3><p>Implementation / run: not supplied.<br>Observed result: not supplied.</p></article></div></div><div class="change-decision"><span class="label">Bounded next decision</span><p>Review the proposed requirement and adverse case. Establish actual owners, implementation and new evidence before making a version-2 claim.</p><button class="inspect" data-inspect="Change and evidence boundary">Inspect what is missing</button></div>'''
make('change','a','The impact field','What may change, and where does the evidence stop?','Trace','One proposition forks into distinct requirement and adverse-test artifacts; the historical evidence sits outside the candidate path.',body,'.impact-field{display:grid;grid-template-columns:470px minmax(0,1fr);gap:60px;margin-top:38px}.revision-folio{padding:30px 35px 0 0;border-top:1px solid #819a74}.revision-folio h2{font-size:48px;margin:25px 0 15px}.baseline-rule{font-size:12px;color:#75846d}.revision-addition{border-left:2px solid #a08a55;padding:20px 25px;margin:32px 0 38px;background:#eee9d7;transition:opacity .2s}.revision-addition p{font-size:24px;line-height:1.45;margin:15px 0 20px}.impact-tree{position:relative;height:725px}.impact-tree>.graphic{position:absolute;inset:0;width:100%;height:100%}.impact-requirement{position:absolute;top:15px;left:32%;width:360px;padding:24px 28px;background:#fffefa;border-top:2px solid #798e6a;box-shadow:8px 8px 0 #e3e9d8;transition:opacity .2s}.impact-requirement h3{font-size:25px;margin:16px 0}.impact-requirement p{font-size:15px}.impact-test{position:absolute;top:310px;left:32%;width:360px;padding:22px 28px;border-block:1px dashed #9aac89;background:#eef0e6;transition:opacity .2s}.impact-test h3{font-size:25px;margin:16px 0}.impact-test dl{margin:0}.impact-test dl>div{display:grid;grid-template-columns:80px 1fr;gap:18px;padding:10px 0;border-top:1px solid #c5d0b9;font-size:14px}.impact-test dd{margin:0}.impact-test dt{color:#79866f}.impact-evidence{position:absolute;bottom:5px;left:24%;width:410px;padding:20px 28px;border-left:3px solid #8c9b7c;background:#ebece1}.impact-evidence h3{font-size:24px;margin:12px 0}.impact-evidence p{font-size:13px}.change-decision{display:grid;grid-template-columns:210px 1fr 220px;gap:45px;border-top:1px solid #a4b196;padding-top:24px;font-size:16px}',risk='Spatial fan-out may imply actual changes; candidates use dashed relationships, and implementation is stopped at a human decision.')
# CHANGE B — version fault line. Historical scope is literally separated.
body=intro('03 / Scope survives a change','Evidence belongs<br>to a version.','A proposed instruction creates a new question. The earlier record stays attached to the scope it actually describes.')+change_controls+'''<section class="version-planes"><article class="baseline-plane"><div class="version-label"><strong>v1</strong><span>Teaching baseline<br>No implementation asserted</span></div><div class="baseline-statement"><span class="mono">CHG-INS@1</span><h2>Describe the missing<br>item before handoff.</h2></div><div class="evidence-pin"><span class="pin-dot"></span><p class="label">Records scope for this instruction</p><div class="evidence-receipt"><div><span class="mono">CHG-EVID@1</span><span class="status missing">No observed result</span></div><h3>A retained evidence structure</h3><dl><div><dt>Instruction scope</dt><dd>CHG-INS@1</dd></div><div><dt>Implementation / run</dt><dd>Not supplied</dd></div><div><dt>Observed outcome</dt><dd>Not supplied</dd></div></dl></div></div></article><div class="version-fault"><div>VERSION<br>BOUNDARY</div><svg viewBox="0 0 100 600" role="img" aria-label="Evidence cannot cross automatically"><path d="M50 0V600" stroke="#ac986c" stroke-width="2" stroke-dasharray="7 8"/><path d="M0 300H100" stroke="#ac986c"/><path d="M38 287L64 313M64 287L38 313" stroke="#765f32" stroke-width="2"/></svg><p>Does not<br>verify v2</p></div><article class="candidate-plane" data-revision><div class="version-label"><strong>v2</strong><span>Proposed revision<br>Not approved or implemented</span></div><div class="candidate-statement"><span class="mono">CHG-INS@2</span><h2>Also retain the source<br>and responsibility gap.</h2></div><div class="new-evidence-slot"><span class="label">New coverage is not supplied</span><h3>What would support<br>this revised behaviour?</h3><div class="needed-row"><span>01</span><p>Review CHG-REQ@1<br><small>Expected behaviour and permitted workflow</small></p></div><div class="needed-row"><span>02</span><p>Challenge CHG-TEST@1<br><small>Unknown owner stays unresolved</small></p></div><div class="needed-row"><span>03</span><p>Record an actual result<br><small>Real implementation, fixture, version and outcome</small></p></div></div></article></section><div class="version-foot"><strong>Nothing moves across by assumption.</strong><p>A colleague decides the change. A relevant new observation—not the diagram—would establish evidence for the revised scope.</p><button class="inspect" data-inspect="Historical evidence scope">Inspect the retained record</button></div>'''
make('change','b','The version fault line','What may change, and where does the evidence stop?','Compare','A full-height version seam separates a pinned historical record from an open evidence requirement; no arrow completes the gap.',body,'.version-planes{display:grid;grid-template-columns:minmax(0,1fr) 150px minmax(0,1fr);gap:45px;margin-top:35px;min-height:710px}.version-label{display:flex;align-items:center;gap:30px;border-top:1px solid #a6b49b;padding:22px 0;color:#78846d}.version-label strong{font-size:78px;line-height:1;letter-spacing:-.065em;font-weight:400;color:#31573e}.version-label span{font-size:13px}.baseline-statement,.candidate-statement{padding:25px 0}.baseline-statement h2,.candidate-statement h2{font-size:35px;margin-top:15px}.evidence-pin{position:relative;padding:50px 0 0 55px;border-left:1px solid #a3b493;margin:5px 0 0 20px}.pin-dot{position:absolute;left:-5px;top:0;width:9px;height:9px;border-radius:50%;background:#426646}.evidence-pin>.label{margin-bottom:20px}.evidence-receipt{border-top:2px solid #7e9370;border-bottom:1px dashed #8da07d;background:#edeee3;padding:24px 30px}.evidence-receipt>div{display:flex;gap:20px;align-items:center;justify-content:space-between}.evidence-receipt h3{font-size:27px;margin:25px 0}.evidence-receipt dl{margin:0}.evidence-receipt dl>div{display:flex;justify-content:space-between;border-top:1px solid #c5ceba;padding:13px 0;font-size:14px}.evidence-receipt dd{margin:0}.evidence-receipt dt{color:#718066}.version-fault{position:relative;display:flex;align-items:center;flex-direction:column;padding-top:30px}.version-fault>div{font-size:11px;text-align:center;letter-spacing:.14em;color:#8c7950;background:#f5f4ed;z-index:1;padding:8px}.version-fault svg{height:600px;width:100px}.version-fault p{position:absolute;top:390px;text-align:center;background:#f5f4ed;padding:12px;font-size:15px;color:#876f3c}.candidate-plane{transition:opacity .2s}.candidate-plane .version-label strong{color:#937c48}.new-evidence-slot{border:1px dashed #b2a075;padding:25px 30px;margin:5px 0 0 30px;position:relative;background:repeating-linear-gradient(-45deg,transparent,transparent 10px,#eeeadd33 10px,#eeeadd33 11px)}.new-evidence-slot h3{font-size:29px;margin:22px 0}.needed-row{display:flex;gap:20px;align-items:start;border-top:1px solid #d1c8ae;padding:14px 0}.needed-row>span{font-size:12px;color:#9b8653}.needed-row p{font-size:18px}.needed-row small{display:block;margin-top:6px}.version-foot{display:grid;grid-template-columns:1fr 1.3fr 240px;gap:45px;border-top:1px solid #b4bea7;padding-top:26px;margin-top:22px}.version-foot strong{font-size:28px;font-weight:400;letter-spacing:-.03em}.version-foot p{font-size:15px}',risk='The left evidence could be mistaken for a prior pass; the record prominently states no observed result, not merely historical.')
# CHANGE C — proposition review ledger, annotations on a document rather than a flow.
body=intro('03 / One change, several review obligations','Read the change.<br>Inspect the consequence.','The proposed revision adds provenance and a responsibility gap. Every row asks what would need to be reviewed—not what has been implemented.')+'''<div class="redline-layout"><section class="redline-document"><header><span class="mono">CHG-INS@1 → CHG-INS@2</span><span class="status proposed">Synthetic proposal</span></header><h2>Onboarding handoff</h2><p class="redline-copy">Describe the missing item before handoff.<br><ins>Retain its source pointer.</ins><br><ins>Identify the follow-up role, or state<br>that responsibility is unresolved.</ins></p><footer>Retained words stay plain. Added propositions are underlined.<br>This is not an authorised policy interpretation.</footer></section><aside class="redline-review"><p class="label">Reviewer’s margin</p><h3>What does this change<br>actually require?</h3><p>Before a real instruction changes, establish applicability, who may accept the change, and the actual system behaviour.</p><div class="gate"><strong>Human decision</strong><p>Accepting this wording does not implement it or produce test evidence.</p></div></aside></div><div class="review-ledger"><div class="ledger-title"><h3>Proposition</h3><h3>Potential consequence</h3><h3>Evidence boundary</h3></div><div class="ledger-row"><p>Source pointer is added</p><p>Review CHG-REQ@1:<br>retain the item and provenance</p><p>Not implemented in this specimen</p></div><div class="ledger-row"><p>Unknown role stays explicit</p><p>Challenge CHG-TEST@1:<br>do not fabricate an owner</p><p>Proposed test; no observed result</p></div><div class="ledger-row"><p>Instruction scope changes</p><p>Retain CHG-EVID@1 under v1</p><p>No version-2 coverage established</p></div></div><div class="ledger-bottom"><button class="inspect" data-inspect="Review the source and proposed instruction">Inspect source and proposal</button><p>Bounded next step: review the candidate requirement and adverse test, then establish actual implementation and new evidence.</p></div>'''
make('change','c','The proposition ledger','What may change, and where does the evidence stop?','Compare','A redline is aligned to its review consequence and missing evidence in an unboxed editorial ledger.',body,'.redline-layout{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(0,1fr);gap:90px}.redline-document{background:#fffefa;padding:30px 46px;border-top:2px solid #607b52}.redline-document>header{display:flex;justify-content:space-between;align-items:center}.redline-document h2{font-size:31px;margin:30px 0}.redline-copy{font-size:33px;line-height:1.65;letter-spacing:-.02em}.redline-copy ins{background:#e4ead7;text-decoration-color:#9d8959;text-underline-offset:7px;text-decoration-thickness:1px}.redline-document footer{font-size:12px;color:#7a866f;margin-top:28px}.redline-review{padding-top:25px}.redline-review h3{font-size:33px;margin:25px 0}.redline-review>p{font-size:17px;color:#6d7e63}.redline-review .gate{margin-top:40px}.review-ledger{margin-top:40px}.ledger-title,.ledger-row{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:60px;border-bottom:1px solid #c5cfb8;padding:18px 0}.ledger-title h3{font-size:13px;color:#7a866e;text-transform:uppercase;letter-spacing:.07em}.ledger-row{font-size:18px;line-height:1.6}.ledger-row>p:last-child{font-size:15px;color:#8a7447}.ledger-bottom{display:flex;justify-content:space-between;align-items:start;margin-top:28px;gap:80px}.ledger-bottom p{font-size:14px;max-width:80ch}',risk='A neat ledger may imply the review is complete; every consequence is proposed and the evidence gaps remain explicit.')
(R/'review'/'DIRECTION_NOTES.json').write_text(json.dumps(notes,indent=2)+'\n')
# Lightweight directory: these are compositions, not a new product navigation system.
for scene in ['overview','knowledge','change']:
 links=''.join(f'<a href="direction-{d}/"><span>{d.upper()}</span><h2>{next(n["name"] for n in notes if n["scene"]==scene and n["direction"]==d)}</h2><p>{next(n["visual_idea"] for n in notes if n["scene"]==scene and n["direction"]==d)}</p></a>' for d in 'abc')
 (R/scene/'index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><title>{scene} directions</title><link rel="stylesheet" href="../shared/base.css"><main class="canvas"><p class="label">1920×1200 composition exploration</p><h1>{scene.title()}</h1><section style="display:grid;gap:40px;margin-top:70px">{links}</section></main></html>')
